import type { Poll } from "@kurasu/contract/polls";

import type { EndpointError, QueryOptions } from "../../api/api-error.ts";
import { queryKeys } from "../../api/query-keys.ts";
import type { PollFilters } from "../../api/query-keys.ts";
import { useApiQuery } from "../../api/useApiQuery.ts";

export const usePolls = (
  filters: PollFilters,
  options?: QueryOptions<ReadonlyArray<Poll>, EndpointError<"polls", "list">>,
) =>
  useApiQuery({
    queryKey: queryKeys.polls(filters),
    call: (api) => api.polls.list({ query: filters }),
    options,
  });
import type { Question } from "@kurasu/contract/questions";

import type { EndpointError, QueryOptions } from "../../api/api-error.ts";
import { queryKeys } from "../../api/query-keys.ts";
import { useApiQuery } from "../../api/useApiQuery.ts";

export const useQuestions = <D = ReadonlyArray<Question>>(
  sessionId: string,
  options?: QueryOptions<ReadonlyArray<Question>, EndpointError<"questions", "list">, D>,
